        if len(phs) == 1 and phs[0][2].strip() in ("%", "R$ bilhões", "US$ bilhões") or re.match(r"^(%|R\$|US\$)", phs[0][2]) and len(phs) == 1:
            unit = phs[0][2]
            continue
