        for p in others:
            hit = [k for k, c in enumerate(cols) if c[0] - 8 <= (p[0] + p[1]) / 2 <= c[1] + 8 or (p[0] - 4 <= c[2] <= p[1] + 4)]
            if not hit:
                hit = [col_of((p[0] + p[1]) / 2)]
            # frases largas e únicas na linha (ex. "Variação anual") cobrem um bloco
            for k in hit:
                labels[k].append(("o", p[2]))
