            label = "(linha)"
        rows_out.append({"label": label, "group": group,
                         "cells": [(col_names[k], v) for k, v in sorted(cells.items())]})
    notes = []
    for lj in range(reg["li_end"] - 0, reg["li_end"] + 1):
        pass
    return {"unit": unit, "cols": col_names, "rows": rows_out}


