    out = []
    for lj in range(reg["li"], reg["li_end"] + 1):
        ws = [w for w in lines[lj]["w"] if reg["x0r"] <= w[0] < reg["x1r"]]
        if ws:
            out.append(" ".join(w[4] for w in ws))
    return out


